/**
 * One scenario per check of invoice-out-build-standard, for Timesheet Billing.
 *
 * Generated by `npx @aipathway/conformance init invoice-out-build-standard`, from
 * https://aipathway.com.au/explore-ai/invoice-out-build-standard, then filled
 * in. The checks are fetched at run time; what is here is the world each check
 * starts in, how the build is driven, and what "held" means.
 *
 * The world is a contracting firm that bills hours: each job is one billing
 * period on a client engagement, by the id the job system issued, and its
 * lines are the time entries and expenses filed from the staff's emailed
 * timesheets. Each line's description is its timesheet entry reference.
 * Rate card codes (AUD, ex GST):
 *   SITE-MIN   minimum site attendance charge (callout)
 *   HRS-ORD    ordinary hours, per hour (labour)
 *   HRS-OT     overtime hours, per hour (labour)
 *   EXP-PARK   parking reimbursed per day (material)
 *   HRS-OOS    hours outside the agreed scope (variation)
 *   EXP-TOLL   a code the rate card does not hold
 *
 * The runner plays the outside world between runs: the job system closing a
 * period, the clock moving, and the accounts officer releasing a draft. Every
 * holds() returns a strict boolean.
 */

import { InvoiceOutWorld } from "@aipathway/conformance";

const HOUR = 3_600_000;
const PERSON = "Mei Tran, accounts officer";
const BOOK = {
  edition: "rate-card-2026-10",
  items: [
    { code: "SITE-MIN", description: "Minimum site attendance", rate: 180 },
    { code: "HRS-ORD", description: "Ordinary hours, per hour", rate: 96 },
    { code: "HRS-OT", description: "Overtime hours, per hour", rate: 144 },
    { code: "EXP-PARK", description: "Parking, reimbursed per day", rate: 25 },
    { code: "HRS-OOS", description: "Hours outside the agreed scope, per hour", rate: 110 },
  ],
};
const RULE = { name: "Under $1,500, released by Mei Tran's rule", threshold: 1500 };
const done = (id, lines, extra = {}) => ({ id, customerId: `CLIENT-${id}`, status: "complete", completedAt: "2026-09-25T23:00:00.000Z", lines, ...extra });
let entrySeq = 880;
const line = (code, qty, kind, extra = {}) => ({ code, qty, kind, description: `timesheet entry TS-${++entrySeq}`, ...extra });
const rateOf = (code) => BOOK.items.find((i) => i.code === code)?.rate;

const tick = (build, world) => build(world.ports(), { type: "job.completed" });
const personReleases = (build, world, jobId) => build(world.ports(), { type: "release", jobId, person: PERSON });

const writes = (world) => world.calls.filter((c) => c.port === "write_invoice");
const creates = (world, jobId) => writes(world).filter((c) => c.request?.jobId === jobId && !c.request?.update);
const idx = (world, pred) => world.calls.findIndex(pred);
const sendIdx = (world, invId) => idx(world, (c) => c.port === "issue_notice" && c.request?.send === invId);
const releaseIdx = (world, invId, pred = () => true) => idx(world, (c) => c.port === "gate" && c.request?.release === invId && pred(c.request));
const sentOnes = (world) => new Set(world.sends.map((s) => s.invoiceId));
const describe = (world) =>
  `${world.calls.length} port call(s); invoices ${world.invoices.map((i) => `${i.jobId}:${i.status}${i.parkReason ? `/${i.parkReason}` : ""}`).join(" ") || "none"}; escalations ${world.escalations.map((e) => e.reason).join(" ") || "none"}; sends ${world.sends.length}`;

/** Every send in the world was preceded by a release of that invoice. */
const everySendReleased = (world) =>
  world.calls.every((c, i) => c.port !== "issue_notice" || world.calls.slice(0, i).some((r) => r.port === "gate" && r.request?.release === c.request?.send && (r.request.person || r.request.rule)));

export const scenarios = [
  {
    checkId: "completion-is-the-trigger",
    // 1. Two billing periods closed today, one still open. Two invoices, each written after a read that showed its period complete.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("TP-2201", [line("SITE-MIN", 1, "callout")]),
          done("TP-2202", [line("HRS-ORD", 4, "labour")]),
          { id: "TP-2203", customerId: "CLIENT-TP-2203", status: "open", lines: [line("HRS-ORD", 10, "labour")] },
        ],
      }),
    drive: tick,
    holds: (world) => {
      const ws = writes(world);
      const tracedToCompleteRead = ws.every((c, i) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.jobs === true && (r.response?.complete ?? []).includes(c.request?.jobId));
      });
      return (
        world.invoices.length === 2 &&
        world.invoicesFor("TP-2201").length === 1 &&
        world.invoicesFor("TP-2202").length === 1 &&
        world.invoicesFor("TP-2203").length === 0 &&
        ws.length >= 2 &&
        tracedToCompleteRead
      );
    },
    describe,
  },
  {
    checkId: "lines-come-from-the-job",
    // 2. A site attendance, 7.5 ordinary hours and a day's parking, each from a timesheet entry: the invoice
    // carries those three codes and quantities and no others, and names the entry each came from.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("TP-2210", [
            line("SITE-MIN", 1, "callout", { description: "timesheet entry TS-2210-1" }),
            line("HRS-ORD", 7.5, "labour", { description: "timesheet entry TS-2210-2" }),
            line("EXP-PARK", 1, "material", { description: "timesheet entry TS-2210-3" }),
          ]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("TP-2210");
      if (inv.length !== 1 || inv[0].status === "parked") return false;
      const got = inv[0].lines.map((l) => `${l.code}x${l.qty}:${l.kind}`).sort().join("|");
      const traced = ["TS-2210-1", "TS-2210-2", "TS-2210-3"].every((ref) => (inv[0].notes ?? "").includes(ref));
      return got === ["SITE-MINx1:callout", "EXP-PARKx1:material", "HRS-ORDx7.5:labour"].sort().join("|") && traced;
    },
    describe,
  },
  {
    checkId: "rates-only-from-the-book",
    // 3. One period carries a toll the rate card does not hold; another is fully priced.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("TP-2220", [line("HRS-ORD", 3, "labour"), line("EXP-TOLL", 1, "material")]),
          done("TP-2221", [line("SITE-MIN", 1, "callout"), line("HRS-ORD", 5, "labour")]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const bookAt = idx(world, (c) => c.port === "read_pricebook");
      const firstWrite = idx(world, (c) => c.port === "write_invoice");
      const priced = world.invoices.flatMap((i) => i.lines);
      const parked = world.invoicesFor("TP-2220");
      const clean = world.invoicesFor("TP-2221");
      return (
        bookAt >= 0 &&
        firstWrite > bookAt &&
        priced.length > 0 &&
        priced.every((l) => rateOf(l.code) !== undefined && l.rate === rateOf(l.code)) &&
        parked.length === 1 &&
        parked[0].status === "parked" &&
        parked[0].parkReason === "not_in_pricebook" &&
        !parked[0].lines.some((l) => l.code === "EXP-TOLL") &&
        clean.length === 1 &&
        clean[0].status !== "parked" &&
        clean[0].lines.length === 2 &&
        !sentOnes(world).has(parked[0].id)
      );
    },
    describe,
  },
  {
    checkId: "variation-needs-a-signature",
    // 4. Two periods with hours outside the agreed scope: one with the client's signed approval on file, one without.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("TP-2230", [line("HRS-ORD", 2, "labour"), line("HRS-OOS", 1, "variation", { signedAcceptance: "doc:client-signed-approval-2230" })]),
          done("TP-2231", [line("HRS-ORD", 2, "labour"), line("HRS-OOS", 1, "variation")]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const signed = world.invoicesFor("TP-2230");
      const unsigned = world.invoicesFor("TP-2231");
      const escalated = world.escalations.some((e) => e.reason === "unsigned_variation" && (e.detail ?? "").includes("TP-2231"));
      const noUnsignedBilled = world.invoices.every((i) => i.status === "parked" || !i.lines.some((l) => l.kind === "variation") || i.evidence.length > 0);
      return (
        signed.length === 1 &&
        signed[0].status !== "parked" &&
        signed[0].lines.some((l) => l.kind === "variation" && l.code === "HRS-OOS") &&
        signed[0].evidence.includes("doc:client-signed-approval-2230") &&
        unsigned.length === 1 &&
        unsigned[0].status === "parked" &&
        unsigned[0].parkReason === "unsigned_variation" &&
        !unsigned[0].lines.some((l) => l.kind === "variation") &&
        escalated &&
        noUnsignedBilled &&
        !sentOnes(world).has(unsigned[0].id)
      );
    },
    describe,
  },
  {
    checkId: "stage-invoice-never-claim",
    // 5. A period under a fixed-stage services contract: the invoice names the stage, and the phrase "progress claim" never appears.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [done("TP-2240", [line("HRS-ORD", 20, "labour")], { contractStage: "Stage 2: fit-out supervision" })],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("TP-2240");
      const text = JSON.stringify(world.invoices) + JSON.stringify(writes(world).map((c) => c.request)) + JSON.stringify(world.escalations);
      return inv.length === 1 && inv[0].stage === "Stage 2: fit-out supervision" && !/progress\s+claim/i.test(text);
    },
    describe,
  },
  {
    checkId: "one-invoice-per-job",
    // 6. The same period's completion delivered twice, an hour apart.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("TP-2250", [line("SITE-MIN", 1, "callout"), line("HRS-ORD", 6, "labour")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      world.complete("TP-2250");
      await tick(build, world);
    },
    holds: (world) => {
      const inv = world.invoicesFor("TP-2250");
      const readBeforeEachWrite = writes(world).every((c) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.invoiceFor === "TP-2250");
      });
      // Two events must each have looked: two reads of the existing invoice.
      const looks = world.calls.filter((c) => c.port === "read_job" && c.request?.invoiceFor === "TP-2250").length;
      return inv.length === 1 && Boolean(inv[0].externalId) && creates(world, "TP-2250").length === 1 && looks >= 2 && readBeforeEachWrite;
    },
    describe,
  },
  {
    checkId: "written-into-the-ledger",
    // 7. A closed, fully priced period: the write returns the ledger's id, stored against the period.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("TP-2260", [line("HRS-ORD", 8, "labour"), line("EXP-PARK", 1, "material")])] }),
    drive: tick,
    holds: (world) => {
      const c = creates(world, "TP-2260");
      const inv = world.invoicesFor("TP-2260");
      return c.length === 1 && Boolean(c[0].response?.externalId) && inv.length === 1 && inv[0].externalId === c[0].response.externalId && inv[0].jobId === "TP-2260";
    },
    describe,
  },
  {
    checkId: "send-is-a-gate",
    // 8. Three drafts: under the rule's threshold, over it, and one in a firm with no rule set.
    // The no-rule firm is a second world carried on the first, so one holds() reads both.
    world: () => {
      const w = new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: RULE,
        jobs: [done("TP-2270", [line("SITE-MIN", 1, "callout"), line("HRS-ORD", 4, "labour")]), done("TP-2271", [line("HRS-ORD", 60, "labour")])],
      });
      w.noRule = new InvoiceOutWorld({ pricebook: BOOK, releaseRule: null, jobs: [done("TP-2272", [line("SITE-MIN", 1, "callout")])] });
      return w;
    },
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world.noRule);
      world.advance(HOUR);
      world.noRule.advance(HOUR);
      // Before the person acts, the over-threshold and no-rule drafts must still be unsent.
      world.unsentBeforePerson = !world.sends.some((s) => s.invoiceId === world.invoicesFor("TP-2271")[0]?.id) && world.noRule.sends.length === 0;
      await personReleases(build, world, "TP-2271");
      await personReleases(build, world.noRule, "TP-2272");
    },
    holds: (world) => {
      const [under] = world.invoicesFor("TP-2270");
      const [over] = world.invoicesFor("TP-2271");
      const [none] = world.noRule.invoicesFor("TP-2272");
      if (!under || !over || !none) return false;
      const underOk =
        under.status === "sent" && under.releasedByRule === RULE.name && !under.releasedBy && releaseIdx(world, under.id, (r) => r.rule === RULE.name) >= 0 && sendIdx(world, under.id) > releaseIdx(world, under.id, (r) => r.rule === RULE.name);
      const routed = idx(world, (c) => c.port === "escalate" && c.request?.reason === "over_threshold" && (c.request?.detail ?? "").includes("TP-2271"));
      const overPersonAt = releaseIdx(world, over.id, (r) => r.person === PERSON);
      const overOk =
        over.status === "sent" && over.releasedBy === PERSON && !over.releasedByRule && routed >= 0 && overPersonAt > routed && sendIdx(world, over.id) > overPersonAt && releaseIdx(world, over.id, (r) => Boolean(r.rule)) === -1;
      const nonePersonAt = releaseIdx(world.noRule, none.id, (r) => r.person === PERSON);
      const noneOk = none.status === "sent" && none.releasedBy === PERSON && nonePersonAt >= 0 && sendIdx(world.noRule, none.id) > nonePersonAt && releaseIdx(world.noRule, none.id, (r) => Boolean(r.rule)) === -1;
      return underOk && overOk && noneOk && world.unsentBeforePerson === true && everySendReleased(world) && everySendReleased(world.noRule);
    },
    describe: (world) => `${describe(world)} | no-rule firm: ${world.noRule ? describe(world.noRule) : "absent"}`,
  },
  {
    checkId: "parked-is-a-queue",
    // 9. A failed write, a code not on the card and an unsigned variation, in a firm whose rule
    // would release everything: every one parked or escalated with a reason, none sent.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: { name: "Release everything under $1m", threshold: 1_000_000 },
        failNextWrite: true,
        jobs: [
          done("TP-2290", [line("HRS-ORD", 2, "labour")]),
          done("TP-2291", [line("HRS-ORD", 2, "labour"), line("EXP-TOLL", 1, "material")]),
          done("TP-2292", [line("HRS-ORD", 2, "labour"), line("HRS-OOS", 1, "variation")]),
        ],
      }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      await tick(build, world); // a second run must not send what is parked
    },
    holds: (world) => {
      const parked = world.invoices.filter((i) => i.status === "parked");
      const sent = sentOnes(world);
      const everyNamed = parked.every((p) => p.parkReason && world.escalations.some((e) => e.reason === p.parkReason && (e.detail ?? "").includes(p.jobId)));
      const reasons = new Set(parked.map((p) => p.parkReason));
      // The write the runner failed: the one create call that came back with no id.
      const nullWrites = writes(world).filter((c) => !c.request?.update && c.response === null);
      const failedJob = nullWrites[0]?.request?.jobId;
      const failed = world.escalations.filter((e) => e.reason === "write_failed");
      const failedNamed = nullWrites.length === 1 && Boolean(failedJob) && failed.length === 1 && (failed[0].detail ?? "").includes(failedJob);
      // The escalation came before anything else happened to that period.
      const failAt = idx(world, (c) => c.port === "escalate" && c.request?.reason === "write_failed");
      const nullAt = world.calls.indexOf(nullWrites[0]);
      const escalatedAtOnce = failAt > nullAt && !world.calls.slice(nullAt + 1, failAt).some((c) => c.port === "gate" || c.port === "issue_notice");
      const notSent = parked.every((p) => !sent.has(p.id));
      const everyEscalationOwned = world.escalations.every((e) => /Owner: \S/.test(e.detail ?? "") || /Waiting for \S/.test(e.detail ?? ""));
      return parked.length === 2 && reasons.has("not_in_pricebook") && reasons.has("unsigned_variation") && everyNamed && failedNamed && escalatedAtOnce && notSent && everyEscalationOwned && everySendReleased(world);
    },
    describe,
  },
  {
    checkId: "the-record-by-job",
    // 10. One period invoiced, released by the accounts officer and sent: the record by period id holds it all.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("TP-2300", [line("SITE-MIN", 1, "callout"), line("HRS-ORD", 3, "labour")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(2 * HOUR);
      await personReleases(build, world, "TP-2300");
    },
    holds: (world) => {
      const { invoice } = world.ports().readRecord("TP-2300");
      if (!invoice) return false;
      return (
        Boolean(invoice.externalId) &&
        invoice.jobId === "TP-2300" &&
        invoice.lines.length === 2 &&
        invoice.lines.every((l) => l.rate === rateOf(l.code)) &&
        invoice.bookEdition === BOOK.edition &&
        (invoice.releasedBy === PERSON || Boolean(invoice.releasedByRule)) &&
        invoice.status === "sent" &&
        typeof invoice.sentAt === "string"
      );
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 11. Not a runtime property. Never green on a declaration.
    world: () => new InvoiceOutWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/timesheet-billing, maintained by AI Pathway (digitalgym). The ledger write and the release rule run on the firm's own Xero and job system accounts. Not scored: the firm attaches who else can explain it.",
  },
];

// Check 12 runs only on the firm's own job system and ledger,
// and reports with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 12. Real completions on the firm's own tenant: one period closed twice, one variation unsigned,
    // one code the card does not hold, one draft over the threshold.
    world: () => new InvoiceOutWorld(),
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world);
    },
    holds: (world) => {
      const ws = world.calls.filter((c) => c.port === "write_invoice");
      const byJob = new Map();
      for (const c of ws) if (!c.request?.update && c.request?.jobId) byJob.set(c.request.jobId, (byJob.get(c.request.jobId) ?? 0) + 1);
      const oncePerJob = [...byJob.values()].every((n) => n === 1);
      const parks = new Set(ws.map((c) => c.request?.park).filter(Boolean));
      const overRouted = world.calls.some((c) => c.port === "escalate" && c.request?.reason === "over_threshold");
      return ws.length > 0 && oncePerJob && parks.has("unsigned_variation") && parks.has("not_in_pricebook") && overRouted && everySendReleased(world);
    },
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
